import React from 'react';

export default function PhoneSalesResult({ monthlyPlanCost, deviceInstallment, totalPayment, savings, discountType }) {
  const sign = savings > 0 ? '+' : savings < 0 ? '-' : '';
  const abs = Math.abs(savings);
  const label = discountType === 'contract'
    ? '요금할인 절감액'
    : discountType === 'subsidy'
      ? '공시 지원금 절감액'
      : '';

  return (
    <div className="bg-gray-100 p-4 rounded-lg space-y-2">
      <p className="text-lg">월 요금제: <strong>{monthlyPlanCost.toLocaleString()}원</strong></p>
      <p className="text-lg">단말 할부 대금: <strong>{deviceInstallment.toLocaleString()}원</strong></p>
      <p className="text-lg">월 총 납부 예상 금액: <strong>{totalPayment.toLocaleString()}원</strong></p>
      {label && (
        <p className={`text-lg ${savings >= 0 ? 'text-green-600' : 'text-red-600'}`}>
          {label}: {sign}{abs.toLocaleString()}원
        </p>
      )}
      {/* 경고 문구 */}
      <p className="mt-2 text-base font-bold text-red-500">경고! 본 견적은 대략적인 결과 값 입니다.</p>
    </div>
  );
}